<?php

declare(strict_types=1);
$root=rtrim((string)(getenv('PLANEX_ROOT')?:''),'/');$out=(string)(getenv('OUT_JSON')?:'/tmp/waste_current_identities.json');if($root===''||!is_file($root.'/.env')||!is_file($root.'/bootstrap/app.php'))throw new RuntimeException('root invalid');
require_once $root.'/app/Support/helpers.php';require_once $root.'/app/Support/environment.php';loadEnvFileNonOverwriting($root.'/.env');$config=require $root.'/bootstrap/app.php';require_once $root.'/app/Support/crypto_helper.php';require_once $root.'/app/Support/company_database.php';
function ro(array $c):PDO{$p=new PDO('mysql:host='.$c['host'].';port='.($c['port']??3306).';dbname='.$c['database'].';charset=utf8mb4',$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$p->exec('SET SESSION TRANSACTION READ ONLY');$p->exec('START TRANSACTION READ ONLY');return $p;}
function cols(PDO $p,string $t):array{$s=$p->prepare('SELECT COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$s->execute([$t]);return $s->fetchAll();}
function names(array $meta):array{return array_column($meta,'COLUMN_NAME');}
function selectSafe(PDO $p,string $table,array $wanted):array{$meta=cols($p,$table);$n=names($meta);$sel=array_values(array_filter($wanted,fn($x)=>in_array($x,$n,true)));if(!$sel)return[];return $p->query('SELECT '.implode(',',array_map(fn($x)=>'`'.str_replace('`','``',$x).'`',$sel)).' FROM `'.$table.'` ORDER BY id')->fetchAll();}
$central=ro($config['database']);$co=$central->query("SELECT * FROM companies WHERE id=25 AND status='active' LIMIT 1")->fetch()?:null;if(!$co)throw new RuntimeException('company unavailable');$tenant=ro(companyDatabaseConfig($config,$co));
$clientMeta=cols($tenant,'clients');
$contractors=selectSafe($tenant,'contractors',['id','name','inn','status','deleted_at','created_at']);
$drivers=selectSafe($tenant,'drivers',['id','full_name','status','deleted_at','created_at']);
$vehicles=selectSafe($tenant,'vehicle_units',['id','brand','model','plate_number','status','deleted_at','created_at']);
$crews=$tenant->query("SELECT cr.id crew_id,cr.contractor_id,c.name contractor_name,c.inn contractor_inn,cd.driver_id,d.full_name driver_name,vu1.id primary_vehicle_id,vu1.brand primary_brand,vu1.plate_number primary_plate,vu2.id secondary_vehicle_id,vu2.brand secondary_brand,vu2.plate_number secondary_plate,cr.status crew_status,cr.deleted_at crew_deleted_at FROM crews cr LEFT JOIN contractors c ON c.id=cr.contractor_id LEFT JOIN crew_drivers cd ON cd.crew_id=cr.id LEFT JOIN drivers d ON d.id=cd.driver_id LEFT JOIN driver_vehicle_blocks dvb ON dvb.id=cr.driver_vehicle_block_id LEFT JOIN vehicle_sets vs ON vs.id=dvb.vehicle_set_id LEFT JOIN vehicle_units vu1 ON vu1.id=vs.primary_vehicle_unit_id LEFT JOIN vehicle_units vu2 ON vu2.id=vs.secondary_vehicle_unit_id ORDER BY cr.id,cd.id")->fetchAll();
$r=['client_schema'=>$clientMeta,'contractors'=>$contractors,'drivers'=>$drivers,'vehicles'=>$vehicles,'crews'=>$crews,'counts'=>['contractors'=>count($contractors),'drivers'=>count($drivers),'vehicles'=>count($vehicles),'crew_rows'=>count($crews)]];file_put_contents($out,json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));echo 'WASTE_CURRENT_IDENTITY_COUNTS='.json_encode($r['counts']).PHP_EOL;echo "WASTE_CURRENT_IDENTITIES=PASS\n";
